If you have access to a good source of words (ie. an
entire on-line dictionary would be nice), you can simply
use brute force to search it.  I just used the rather
meager dictionary supplied on any Unix (/usr/dict/words)
and discovered "Nicaragua" at 1000188.

N=14 i=9 c=3 a=1 r=18 a=1 g=7 u=21 a=1

This is the same value as reported by a previous answer,
although this word has the advantage that it shows up
in the on-line dictionaries I tried, for example, the
American Heritage, at:

http://education.yahoo.com/reference/dictionary/;_ylt=Aji3tkPEAxeRNiQ3Q7xKXfP0HYkC

My brute force search code follows:






#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

static int
value(char* wordbuff)
{
  int value = 1;
  for (char *p=wordbuff; *p && (*p!='&#92;n'); p++) {
    if (isalpha(*p))
      value *= (tolower(*p) - 'a' + 1);
  }
  return value;
}

int
main(int argc, char* argv[])
{
  char wordbuff[100], bestword[100];
  int bestvalue = 0;
  char *filestr = argc>1 ? argv[1] : "/usr/dict/words";

  FILE *f = fopen(filestr, "r");
  if (!f)
    perror("fopen"), exit(-1);

  while (fgets(wordbuff, sizeof(wordbuff), f) != 0) {
    int v = value(wordbuff);
    if (abs(v - 1000000) < abs(bestvalue - 1000000)) {
      strlcpy(bestword, wordbuff, sizeof(bestword));
      bestvalue = v;
    }
  }
  printf("%d for the word %s", bestvalue, bestword);
  for (char *p=bestword; *p && (*p!='&#92;n'); p++) {
    if (isalpha(*p))
      printf("%c=%d ", *p, tolower(*p)-'a'+1);
  }
  printf("&#92;n");
  return 0;
}

